<script setup lang="ts">
import Tree from 'primevue/tree'
import type { TreeNodeDropEvent } from 'primevue/tree'
import type { TreeNode } from 'primevue/treenode'
import type { KnowledgeDetail, KnowledgeTag, KnowledgeTreeNode } from '~/types/domain'

definePageMeta({ layout: 'app' }); useSeoMeta({ title: 'Knowledge' })
type TreeItem = { key: string; label: string; data: KnowledgeTreeNode; children: TreeItem[] }
const api = useApi(); const route = useRoute(); const router = useRouter(); const toast = useToast()
const tree = ref<KnowledgeTreeNode[]>([]); const tags = ref<KnowledgeTag[]>([]); const detail = ref<KnowledgeDetail>(); const loading = ref(true); const detailLoading = ref(false); const error = ref<unknown>(); const selectedKeys = ref<Record<string, boolean>>({}); const editing = ref(false); const creating = ref(false); const dirty = ref(false)
const form = reactive({ title: '', content: '', description: '', sourceUrl: '' }); const createForm = reactive({ title: '', parentId: '' })
const nodes = computed<TreeItem[]>(() => tree.value.map(mapNode))
function mapNode(node: KnowledgeTreeNode): TreeItem { return { key: node.id, label: node.title, data: node, children: node.children.map(mapNode) } }
async function loadTree() { loading.value = true; error.value = undefined; try { [tree.value, tags.value] = await Promise.all([api.get<KnowledgeTreeNode[]>('/knowledge-nodes/tree'), api.get<KnowledgeTag[]>('/tags')]); const queryId = typeof route.query.node === 'string' ? route.query.node : tree.value[0]?.id; if (queryId) await selectNode(queryId) } catch (caught) { error.value = caught } finally { loading.value = false } }
async function selectNode(id: string) { if (dirty.value && !confirm('Discard your unsaved changes?')) return; detailLoading.value = true; try { detail.value = await api.get<KnowledgeDetail>(`/knowledge-nodes/${id}`); selectedKeys.value = { [id]: true }; Object.assign(form, { title: detail.value.title, content: detail.value.content, description: detail.value.description ?? '', sourceUrl: detail.value.sourceUrl ?? '' }); editing.value = false; dirty.value = false; await router.replace({ query: { ...route.query, node: id } }) } finally { detailLoading.value = false } }
async function createNode() { const created = await api.post<{ id: string }>('/knowledge-nodes', { title: createForm.title, parentId: createForm.parentId || undefined }); creating.value = false; createForm.title = ''; await loadTree(); await selectNode(created.id); toast.add({ title: 'Knowledge node created', color: 'success' }) }
async function save() { if (!detail.value) return; const id = detail.value.id; await api.put(`/knowledge-nodes/${id}`, { title: form.title }); await api.put(`/knowledge-nodes/${id}/content`, { content: form.content, expectedUpdatedAtUtc: detail.value.updatedAtUtc }); await api.put(`/knowledge-nodes/${id}/metadata`, { description: form.description || null, sourceUrl: form.sourceUrl || null }); await loadTree(); await selectNode(id); toast.add({ title: 'Knowledge saved', color: 'success' }) }
async function archive() { if (!detail.value || !confirm(`Archive “${detail.value.title}”?`)) return; await api.post(`/knowledge-nodes/${detail.value.id}/archive`); detail.value = undefined; await router.replace({ query: {} }); await loadTree(); toast.add({ title: 'Knowledge archived' }) }
async function toggleTag(tag: KnowledgeTag) { if (!detail.value) return; const attached = detail.value.tags.some(item => item.id === tag.id); if (attached) await api.delete(`/knowledge-nodes/${detail.value.id}/tags/${tag.id}`); else await api.put(`/knowledge-nodes/${detail.value.id}/tags/${tag.id}`); await selectNode(detail.value.id) }
async function onDrop(event: TreeNodeDropEvent) { const dropped = event.dropNode.data as KnowledgeTreeNode; const parentId = event.dropPosition === 0 ? String(event.dropNode.key) : dropped.parentId; await api.put(`/knowledge-nodes/${event.dragNode.key}/position`, { targetParentId: parentId, targetIndex: Math.max(0, event.index) }); await loadTree() }
function onNodeSelect(node: TreeNode) { if (node.key !== undefined) selectNode(String(node.key)) }
watch(form, () => { if (editing.value) dirty.value = true }, { deep: true }); onMounted(loadTree)
</script>

<template><div><CorePageHeader title="Knowledge" description="Capture durable notes without losing topic context."><UButton icon="i-lucide-plus" label="New node" @click="creating = true" /></CorePageHeader><CoreLoadingState v-if="loading" label="Loading knowledge" /><CoreErrorState v-else-if="error" :error="error" @retry="loadTree" /><section v-else class="knowledge-workspace"><aside class="tree-pane"><div class="pane-head"><strong>Topic tree</strong><span>{{ tree.length }} roots</span></div><Tree v-model:selection-keys="selectedKeys" :value="nodes" selection-mode="single" draggable-nodes droppable-nodes class="tree" @node-select="onNodeSelect" @node-drop="onDrop"><template #default="slotProps"><span>{{ slotProps.node.label }}</span></template></Tree><CoreEmptyState v-if="!nodes.length" title="Your knowledge tree is empty" /></aside><section class="detail-pane"><CoreLoadingState v-if="detailLoading" label="Loading note" /><CoreEmptyState v-else-if="!detail" title="Select a topic" description="Choose a node from the tree to read or edit it." /><template v-else><div class="detail-head"><div><CoreStatusBadge :value="detail.status" /><h2>{{ detail.title }}</h2></div><div><UButton v-if="!editing" icon="i-lucide-pencil" label="Edit" color="neutral" variant="outline" @click="editing = true" /><template v-else><UButton label="Cancel" color="neutral" variant="ghost" @click="selectNode(detail.id)" /><UButton label="Save" icon="i-lucide-save" @click="save" /></template></div></div><article v-if="!editing" class="note"><p v-if="detail.description" class="description">{{ detail.description }}</p><div class="content">{{ detail.content || 'No note content yet.' }}</div><a v-if="detail.sourceUrl" :href="detail.sourceUrl" target="_blank" rel="noreferrer">Open source <UIcon name="i-lucide-external-link" /></a></article><form v-else class="edit-form" @submit.prevent="save"><UFormField label="Title"><UInput v-model="form.title" class="w-full" /></UFormField><UFormField label="Description"><UTextarea v-model="form.description" :rows="3" class="w-full" /></UFormField><UFormField label="Content"><UTextarea v-model="form.content" :rows="16" class="w-full" /></UFormField><UFormField label="Source URL"><UInput v-model="form.sourceUrl" type="url" class="w-full" /></UFormField></form><section class="tag-section"><h3>Tags</h3><div><button v-for="tag in tags" :key="tag.id" class="tag" :class="{ active: detail.tags.some(item => item.id === tag.id) }" @click="toggleTag(tag)">{{ tag.name }}</button></div></section><UButton label="Archive node" icon="i-lucide-archive" color="error" variant="ghost" @click="archive" /></template></section></section><div v-if="creating" class="modal-backdrop" @click.self="creating = false"><UCard class="modal"><template #header><h2>Create knowledge node</h2></template><form class="edit-form" @submit.prevent="createNode"><UFormField label="Title" required><UInput v-model="createForm.title" autofocus class="w-full" /></UFormField><UFormField label="Parent"><select v-model="createForm.parentId"><option value="">Root</option><option v-for="node in nodes" :key="node.key" :value="node.key">{{ node.label }}</option></select></UFormField><div class="modal-actions"><UButton label="Cancel" color="neutral" variant="ghost" @click="creating = false" /><UButton type="submit" label="Create" /></div></form></UCard></div></div></template>

<style scoped>
.knowledge-workspace { display: grid; grid-template-columns: minmax(15rem, 22rem) minmax(0, 1fr); min-height: calc(100vh - 10rem); border: 1px solid var(--ui-border); border-radius: .9rem; overflow: hidden; }.tree-pane { border-right: 1px solid var(--ui-border); background: var(--ui-bg-muted); }.pane-head, .detail-head { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem; border-bottom: 1px solid var(--ui-border); }.pane-head span { color: var(--ui-text-muted); font-size: .8rem; }.tree { padding: .75rem; }.tree :deep(ul) { padding-left: 1rem; }.tree :deep(li) { margin: .15rem 0; }.tree :deep(.p-tree-node-content) { display: flex; align-items: center; gap: .4rem; padding: .4rem; border-radius: .45rem; }.tree :deep(.p-tree-node-content:hover) { background: var(--ui-bg-elevated); }.detail-pane { min-width: 0; }.detail-head h2 { margin-top: .4rem; font-size: 1.5rem; font-weight: 700; }.detail-head > div { display: flex; align-items: center; gap: .5rem; }.detail-head > div:first-child { display: block; }.note, .edit-form, .tag-section { width: min(100% - 2rem, var(--devrecall-reading-width)); margin: 1.5rem auto; }.description { color: var(--ui-text-muted); }.content { min-height: 14rem; margin: 1.5rem 0; white-space: pre-wrap; line-height: 1.75; }.note a { color: var(--ui-primary); }.edit-form { display: grid; gap: 1rem; }.tag-section h3 { margin-bottom: .6rem; font-weight: 700; }.tag-section > div { display: flex; flex-wrap: wrap; gap: .4rem; }.tag { padding: .3rem .65rem; border: 1px solid var(--ui-border); border-radius: 999px; font-size: .78rem; }.tag.active { border-color: var(--ui-primary); color: var(--ui-primary); background: color-mix(in srgb, var(--ui-primary) 10%, transparent); }.modal-backdrop { position: fixed; z-index: 100; inset: 0; display: grid; place-items: center; padding: 1rem; background: rgb(2 6 23 / .55); }.modal { width: min(100%, 28rem); }.modal h2 { font-weight: 700; }.modal select { width: 100%; padding: .5rem; border: 1px solid var(--ui-border); border-radius: .5rem; }.modal-actions { display: flex; justify-content: end; gap: .5rem; }
@media (max-width: 760px) { .knowledge-workspace { grid-template-columns: 1fr; }.tree-pane { border-right: 0; border-bottom: 1px solid var(--ui-border); max-height: 18rem; overflow: auto; } }
</style>
